package grupo22.eventocatalogo_service.resilience;
import grupo22.eventocatalogo_service.service.*;
import grupo22.eventocatalogo_service.domain.*;
import grupo22.eventocatalogo_service.repository.*;
import grupo22.eventocatalogo_service.DTO.response.EventResponseDTO;
import grupo22.eventocatalogo_service.security.ServiceTokens;
import grupo22.eventocatalogo_service.timing.TimedTransport;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.jdbc.datasource.embedded.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.web.client.RestClient;
import org.springframework.web.server.ResponseStatusException;
import com.sun.net.httpserver.*;
import java.net.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CoordinationRecoveryTest {
 HttpServer server;ExecutorService workers;EmbeddedDatabase db;TimedTransport transport;EventWorkflow workflow;EventService events;
 final EventResponseDTO dto=new EventResponseDTO();Event entity;final AtomicReference<String> mode=new AtomicReference<>("NONE");final AtomicInteger initAttempts=new AtomicInteger(),enableAttempts=new AtomicInteger(),cancelAttempts=new AtomicInteger(),refundEffects=new AtomicInteger();final Set<String> stock=ConcurrentHashMap.newKeySet();final AtomicBoolean refunded=new AtomicBoolean();final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);
 void start(boolean shortTimeout)throws Exception{workers=Executors.newCachedThreadPool();db=new EmbeddedDatabaseBuilder().generateUniqueName(true).setType(EmbeddedDatabaseType.H2).build();server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.setExecutor(workers);server.createContext("/",this::handle);server.start();String url="http://127.0.0.1:"+server.getAddress().getPort();var env=new MockEnvironment().withProperty("ticketya.resilience.read.window","2").withProperty("ticketya.resilience.read.minimum","2").withProperty("ticketya.resilience.read.concurrent","1");if(shortTimeout)env.setProperty("ticketya.http.command-ms","100");transport=new TimedTransport(env);var tokens=mock(ServiceTokens.class);when(tokens.client(anyString(),anyString())).thenReturn(RestClient.builder().baseUrl(url).requestFactory(transport.factory(false)).requestInterceptor(transport.propagate()).build());events=mock(EventService.class);var repository=mock(EventRepository.class);var sectors=mock(SectorRepository.class);dto.setEventId(1L);dto.setStatus(EventStatus.BORRADOR);when(events.getEventById(1L)).thenReturn(dto);when(events.publishEvent(1L)).thenAnswer(i->{dto.setStatus(EventStatus.PUBLICADO);return dto;});when(events.cancelEvent(eq(1L),anyString())).thenAnswer(i->{dto.setStatus(EventStatus.CANCELADO);return dto;});when(events.suspendOrUpdateStatus(eq(1L),anyString(),anyString())).thenAnswer(i->{dto.setStatus(EventStatus.valueOf(i.getArgument(1,String.class)));return dto;});entity=new Event("test","test","Recital",1L,2L,OffsetDateTime.now().plusDays(8));entity.setEventId(1L);entity.addSectorPrice(new EventSectorPrice(entity,10L,BigDecimal.TEN));when(repository.findById(1L)).thenReturn(Optional.of(entity));when(repository.lockForCancellation(1L)).thenReturn(Optional.of(entity));var sector=new Sector();sector.setSectorId(10L);sector.setType(SectorType.NO_NUMERADO);sector.setCapacity(2);when(sectors.findByVenueVenueId(2L)).thenReturn(List.of(sector));workflow=new EventWorkflow(events,repository,sectors,new DataSourceTransactionManager(db),url,url,url,tokens,env);admin(41);}
 void admin(long id){var jwt=Jwt.withTokenValue("fixture-admin").header("alg","RS256").subject(String.valueOf(id)).claim("token_use","user").claim("jti","authorization-"+id).build();SecurityContextHolder.getContext().setAuthentication(new JwtAuthenticationToken(jwt,List.of(new SimpleGrantedAuthority("ROLE_ADMINISTRADOR"))));}
 void reply(HttpExchange x,int code,String body)throws java.io.IOException{byte[] b=body.getBytes();x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(code,body.isEmpty()?-1:b.length);if(!body.isEmpty())x.getResponseBody().write(b);x.close();}
 void handle(HttpExchange x)throws java.io.IOException{String path=x.getRequestURI().getPath(),body=new String(x.getRequestBody().readAllBytes()),fault=mode.get();if(path.endsWith("/inventario")){initAttempts.incrementAndGet();if(fault.equals("INIT_503")){reply(x,503,"{}");return;}synchronized(stock){stock.add(body);}if(fault.equals("INIT_HOLD")){entered.countDown();try{release.await(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}if(fault.equals("INIT_LOST")){x.close();return;}if(fault.equals("INIT_TIMEOUT"))try{Thread.sleep(500);}catch(InterruptedException e){Thread.currentThread().interrupt();}reply(x,201,"{\"exitoso\":true}");return;}
 if(path.startsWith("/admin/")){cancelAttempts.incrementAndGet();if(fault.equals("CANCEL_503")){reply(x,503,"{}");return;}if(refunded.compareAndSet(false,true))refundEffects.incrementAndGet();if(fault.equals("CANCEL_LOST")){x.close();return;}reply(x,200,"{\"eventoId\":1,\"devoluciones\":[],\"comprasPendientes\":[]}");return;}
 if(path.endsWith("/publicar"))enableAttempts.incrementAndGet();if(fault.equals("LIFECYCLE_503")||fault.equals("BLOCK_503")&&path.endsWith("/cancel-emission")){reply(x,503,"{}");return;}reply(x,204,"");}
 @AfterEach void close()throws Exception{release.countDown();SecurityContextHolder.clearContext();if(server!=null)server.stop(0);if(workers!=null)workers.shutdownNow();if(transport!=null)transport.close();if(db!=null)db.shutdown();}
 PilotReadGuard guard(String field){return (PilotReadGuard)ReflectionTestUtils.getField(workflow,field);}
 void halfOpen(String field){guard(field).circuit().transitionToHalfOpenState();}
 @Test void unavailableInventoryOpensWithoutPublishingAndRecovers()throws Exception{start(false);mode.set("INIT_503");for(int i=0;i<3;i++)assertEquals(503,assertThrows(ResponseStatusException.class,()->workflow.publish(1L)).getStatusCode().value());assertEquals(2,initAttempts.get());assertEquals(EventStatus.BORRADOR,dto.getStatus());verify(events,never()).publishEvent(any());mode.set("NONE");halfOpen("initialization");assertEquals(EventStatus.PUBLICADO,workflow.publish(1L).getStatus());assertEquals(1,stock.size());}
 @ParameterizedTest @ValueSource(strings={"INIT_LOST","INIT_TIMEOUT"}) void completedInitializationWithLostOrTimedOutResponseIsNotReplayedAutomatically(String fault)throws Exception{start(fault.equals("INIT_TIMEOUT"));mode.set(fault);assertThrows(ResponseStatusException.class,()->workflow.publish(1L));assertEquals(EventStatus.BORRADOR,dto.getStatus());assertEquals(1,initAttempts.get());assertEquals(1,stock.size());mode.set("NONE");assertEquals(EventStatus.PUBLICADO,workflow.publish(1L).getStatus());assertEquals(2,initAttempts.get());assertEquals(1,stock.size());verify(events,times(1)).publishEvent(1L);}
 @Test void localPublishedStateSurvivesOpenEnableCircuit()throws Exception{start(false);mode.set("LIFECYCLE_503");for(int i=0;i<3;i++)assertThrows(ResponseStatusException.class,()->workflow.publish(1L));assertEquals(EventStatus.PUBLICADO,dto.getStatus());assertEquals(1,initAttempts.get());assertEquals(2,enableAttempts.get());mode.set("NONE");halfOpen("lifecycle");assertEquals(EventStatus.PUBLICADO,workflow.publish(1L).getStatus());assertEquals(1,initAttempts.get());}
 @Test void saturatedInitializationNeverDispatchesAnotherWrite()throws Exception{start(false);mode.set("INIT_HOLD");var first=workers.submit(()->workflow.publish(1L));try{assertTrue(entered.await(2,TimeUnit.SECONDS));var failure=assertThrows(ResponseStatusException.class,()->workflow.publish(1L));assertEquals(503,failure.getStatusCode().value());assertEquals(1,initAttempts.get());assertEquals(EventStatus.BORRADOR,dto.getStatus());}finally{release.countDown();}assertEquals(EventStatus.PUBLICADO,first.get(3,TimeUnit.SECONDS).getStatus());assertEquals(1,stock.size());}
 @Test void partialCancellationOpenCircuitPreservesOriginalAdmin()throws Exception{start(false);dto.setStatus(EventStatus.PUBLICADO);mode.set("CANCEL_503");assertThrows(ResponseStatusException.class,()->workflow.cancel(1L,"ADMIN",41L));assertEquals(EventStatus.CANCELADO,dto.getStatus());assertEquals(41L,entity.getCancellationAuthorizedAdminId());admin(42);for(int i=0;i<2;i++)assertThrows(ResponseStatusException.class,()->workflow.cancel(1L,"ADMIN",42L));assertEquals(2,cancelAttempts.get());assertEquals(0,refundEffects.get());mode.set("NONE");halfOpen("cancellation");assertEquals(EventStatus.CANCELADO,workflow.cancel(1L,"ADMIN",42L).getStatus());assertEquals(41L,entity.getCancellationAuthorizedAdminId());assertEquals("authorization-41",ReflectionTestUtils.getField(entity,"cancellationAuthorizationJti"));assertEquals(1,refundEffects.get());verify(events,times(1)).cancelEvent(1L,"ADMIN");}
 @Test void refundCoordinationResponseLostKeepsOneOperationAndOriginalAdmin()throws Exception{start(false);dto.setStatus(EventStatus.PUBLICADO);mode.set("CANCEL_LOST");assertThrows(ResponseStatusException.class,()->workflow.cancel(1L,"ADMIN",41L));assertEquals(1,cancelAttempts.get());assertEquals(1,refundEffects.get());mode.set("NONE");admin(42);assertEquals(EventStatus.CANCELADO,workflow.cancel(1L,"ADMIN",42L).getStatus());assertEquals(2,cancelAttempts.get());assertEquals(1,refundEffects.get());assertEquals(41L,entity.getCancellationAuthorizedAdminId());}
 @Test void entryBlockFailureCannotCancelLocally()throws Exception{start(false);dto.setStatus(EventStatus.PUBLICADO);mode.set("BLOCK_503");assertThrows(ResponseStatusException.class,()->workflow.cancel(1L,"ADMIN",41L));assertEquals(EventStatus.PUBLICADO,dto.getStatus());assertEquals(0,cancelAttempts.get());mode.set("NONE");admin(42);assertEquals(EventStatus.CANCELADO,workflow.cancel(1L,"ADMIN",42L).getStatus());assertEquals(41L,entity.getCancellationAuthorizedAdminId());}
 @ParameterizedTest @ValueSource(strings={"suspend","enable"}) void suspensionAndEnableRemainRecoverable(String operation)throws Exception{start(false);dto.setStatus(operation.equals("suspend")?EventStatus.PUBLICADO:EventStatus.AGOTADO);mode.set("LIFECYCLE_503");assertThrows(ResponseStatusException.class,()->{if(operation.equals("suspend"))workflow.suspend(1L,"ADMIN");else workflow.status(1L,"PUBLICADO","ADMIN");});assertEquals(operation.equals("suspend")?EventStatus.SUSPENDIDO:EventStatus.AGOTADO,dto.getStatus());mode.set("NONE");if(operation.equals("suspend"))assertEquals(EventStatus.SUSPENDIDO,workflow.suspend(1L,"ADMIN").getStatus());else assertEquals(EventStatus.PUBLICADO,workflow.status(1L,"PUBLICADO","ADMIN").getStatus());}
}
